import itertools
from itertools import combinations

n = 14
def build_circulant(n, S):
    E = set()
    for i in range(n):
        for s in S:
            j = (i+s) % n
            a,b = min(i,j), max(i,j)
            E.add((a,b))
    return E

def max_clique(n, E):
    adj = [set() for _ in range(n)]
    for u,v in E:
        adj[u].add(v); adj[v].add(u)
    best = 0
    # simple BK
    def bk(R, P, X):
        nonlocal best
        if not P and not X:
            best = max(best, len(R))
            return
        if len(R) + len(P) <= best: return
        for v in list(P):
            bk(R|{v}, P & adj[v], X & adj[v])
            P = P - {v}
            X = X | {v}
    bk(set(), set(range(n)), set())
    return best

def chromatic_upper(n, E, k):
    # try k-coloring
    adj = [set() for _ in range(n)]
    for u,v in E:
        adj[u].add(v); adj[v].add(u)
    color = [-1]*n
    order = sorted(range(n), key=lambda x:-len(adj[x]))
    def go(i):
        if i == n: return True
        v = order[i]
        used = {color[u] for u in adj[v] if color[u]>=0}
        for c in range(k):
            if c not in used:
                color[v]=c
                if go(i+1): return True
                color[v]=-1
        return False
    return go(0), color[:]

for S in [[1,2,3],[1,2,4],[1,2,5],[1,3,5],[1,4,6],[1,2,6],[2,3,4],[1,3,4],[1,3,6],[1,4,5],[2,3,5],[2,3,6],[1,5,6],[2,4,6],[3,4,5],[3,4,6],[3,5,6],[4,5,6]]:
    E = build_circulant(n,S)
    mc = max_clique(n,E)
    mindeg = min(len([1 for u,v in E if u==i or v==i]) for i in range(n))
    if mc<=3 and mindeg>=5:
        ok,col = chromatic_upper(n,E,5)
        print(S, 'clique',mc,'mindeg',mindeg,'5col',ok)
